  player.observeProvince(seller,"广东");player.observeProvince(seller,"未知");assertEquals("广东",market.shop(seller,buyer).get("ipProvince"));ReflectionTestUtils.setField(player,"thresholds","0,100,300");db.run("UPDATE boost_player_profile SET growth_points=150,membership_type='MEMBER',membership_expires_at=? WHERE member_id=?",java.sql.Timestamp.valueOf(java.time.LocalDateTime.now().plusDays(5)),seller);Map<String,Object> home=market.shop(seller,buyer);assertEquals(2,home.get("level"));assertEquals(true,home.get("membershipActive"));assertEquals(25L,num(home,"growthProgress"));db.run("UPDATE boost_player_profile SET membership_expires_at=? WHERE member_id=?",java.sql.Timestamp.valueOf(java.time.LocalDateTime.now().minusDays(1)),seller);assertEquals(false,market.shop(seller,buyer).get("membershipActive"));ReflectionTestUtils.setField(player,"thresholds","");
