 @Test void providerReceiptIsBoundToSessionAndAuthoritativeLibrary(){Map<String,Object>r=map("IsVerifyIntention",false,"Text",map("ErrCode",0,"LiveStatus",0,"Comparestatus",0,"CompareLibType","权威库","Extra","session-1","IdCard","110101199001010011","Name","隔离测试"));assertTrue(BoostIdentityGateway.verified(r,"session-1"));assertFalse(BoostIdentityGateway.verified(r,"wrong-session"));Map<String,Object>t=(Map<String,Object>)r.get("Text");t.put("CompareLibType","用户库");assertFalse(BoostIdentityGateway.verified(r,"session-1"));t.put("CompareLibType","权威库");r.remove("IsVerifyIntention");assertFalse(BoostIdentityGateway.verified(r,"session-1"));r.put("IsVerifyIntention","false");assertFalse(BoostIdentityGateway.verified(r,"session-1"));r.put("IsVerifyIntention",true);assertFalse(BoostIdentityGateway.verified(r,"session-1"));}
