 @Test void simulatedDeliveryRequiresRealOwnedProofAndBuyerConfirmationOnce()throws Exception{long id=active();long o=num(trade.create(buyer,checkout(id),false),"id");trade.simulatedPay(buyer,o);assertEquals("WAIT_DELIVERY",str(trade.detail(o,buyer),"status"));assertEquals("SOLD",str(db.one("SELECT status FROM boost_listing WHERE id=?",id),"status"));assertThrows(BoostException.class,()->trade.action(seller,o,"start"));assertThrows(BoostException.class,()->trade.progress(seller,o,map("percent",100,"note","伪进度","images",List.of(deliveryImage))));assertThrows(BoostException.class,()->trade.action(buyer,o,"confirm"));Map<String,Object>b=map("requestKey",UUID.randomUUID().toString(),"note","已交付约定的两件护甲","images",List.of(deliveryImage));assertThrows(BoostException.class,()->trade.delivery(other,o,b));trade.delivery(seller,o,b);trade.delivery(seller,o,b);assertEquals(1,db.count("SELECT COUNT(*) FROM boost_item_delivery WHERE order_id=?",o));assertEquals("WAIT_CONFIRM",str(trade.detail(o,buyer),"status"));assertNotNull(trade.detail(o,buyer).get("delivery"));assertThrows(BoostException.class,()->trade.action(seller,o,"confirm"));trade.action(buyer,o,"confirm");trade.action(buyer,o,"confirm");assertEquals("COMPLETED",str(trade.detail(o,buyer),"status"));assertEquals(1,db.count("SELECT COUNT(*) FROM boost_ledger WHERE event_key=?","settle:"+o));assertEquals(12000,db.count("SELECT balance_cents FROM boost_member WHERE id=?",seller));assertEquals(0,db.count("SELECT COUNT(*) FROM boost_progress WHERE order_id=?",o));}
