 @Test @Transactional(propagation=Propagation.NOT_SUPPORTED) void simultaneousBuyersCannotBothReserveWholeLot()throws Exception{
  long id=active();Map<String,Object>first=checkout(id),second=new LinkedHashMap<>(first);second.put("requestKey",UUID.randomUUID().toString());
  java.util.concurrent.CountDownLatch start=new java.util.concurrent.CountDownLatch(1);java.util.concurrent.ExecutorService pool=java.util.concurrent.Executors.newFixedThreadPool(2);
  try{List<java.util.concurrent.Future<Boolean>> results=new ArrayList<>();for(int i=0;i<2;i++){final long actor=i==0?buyer:other;final Map<String,Object>body=i==0?first:second;results.add(pool.submit(()->{start.await();try{new org.springframework.transaction.support.TransactionTemplate(tx).execute(status->trade.create(actor,body,false));return true;}catch(BoostException expected){return false;}}));}start.countDown();int successes=0;for(java.util.concurrent.Future<Boolean>r:results)if(r.get(20,java.util.concurrent.TimeUnit.SECONDS))successes++;assertEquals(1,successes);assertEquals(1,db.count("SELECT COUNT(*) FROM boost_order WHERE listing_id=? AND status='WAIT_PAY'",id));assertEquals("RESERVED",str(db.one("SELECT status FROM boost_listing WHERE id=?",id),"status"));}
  finally{pool.shutdownNow();}
 }
